interface.signature:
interface Lesson {
  id: string;
  title: string;
  description: string;
  difficulty: 'beginner' | 'intermediate' | 'advanced';
  wpmThreshold: number;
  accuracyThreshold: number;
  order: number;
  prerequisites: string[]; // lesson IDs
  content: {
    exercises: Exercise[];
    duration: number; // estimated minutes
  };
  isLocked: boolean;
  createdAt: Timestamp;
}

interface UserLessonProgress {
  userId: string;
  lessonId: string;
  status: 'locked' | 'in-progress' | 'completed';
  wpmAchieved: number;
  accuracyAchieved: number;
  completionDate?: Timestamp;
  attempts: number;
  bestWpm: number;
  bestAccuracy: number;
}

interface Achievement {
  id: string;
  name: string;
  description: string;
  icon: string;
  type: 'milestone' | 'performance' | 'progress' | 'completion';
  criteria: {
    type: 'wpm' | 'accuracy' | 'lessons_completed' | 'streak_days';
    value: number;
    condition?: 'greater_than' | 'less_than' | 'equal';
  };
  points: number;
  unlockedAt?: Timestamp;
  userId: string;
}

type Props = {
  text: string;
  typed: string;
  status: AppStatus;
  onType: (value: string) => void;
  actions?: React.ReactNode;
  className?: string;
};

interface LessonProgressBarProps {
  completed: number;
  total: number;
  label?: string;
  className?: string;
}
